const projectStore={projects:clientsState.items.map(c=>({id:'p-'+c.id,clientId:c.id,name:c.project||'Projeto principal',status:'Ativo',archived:false})),clientId:'',projectId:'',query:'',showArchived:false,view:'list',group:'date',dialog:null};
if(!dashState.tasks.length){const next=new Date(),tomorrow=new Date(next.getTime()+864e5);dashState.tasks.push({id:'demo-task-1',title:'Planejar campanha',clientId:'1',client:clientsState.items[0].name,projectId:'p-1',due:dashToday(),status:'A Fazer',done:false,archived:false},{id:'demo-task-2',title:'Revisar materiais',clientId:'2',client:clientsState.items[1].name,projectId:'p-2',due:tomorrow.toISOString().slice(0,10),status:'Em Progresso',done:false,archived:false})}
function getProject(id){return projectStore.projects.find(p=>p.id===id)}
function projectTasks(c){return dashState.tasks.filter(t=>t.clientId===c.id)}
function projectPanel(c){if(!c)return '<p class="small-note">Salve o cliente para vincular projetos e tarefas.</p>';const projects=projectStore.projects.filter(p=>p.clientId===c.id&&!p.archived),tasks=projectTasks(c);return `<div class="project-head"><p>Projetos e tarefas vinculados a este cliente.</p><div><button type="button" class="c-btn" data-project="open-board" data-id="${c.id}">Abrir quadro ↗</button><button type="button" class="c-btn primary" data-project="new-project" data-id="${c.id}">＋ Projeto</button></div></div><div class="project-label">▱ PROJETOS (${projects.length})</div>${projects.length?projects.map(p=>`<div class="project-entry"><button type="button" data-project="open-project" data-id="${p.id}">${esc(p.name)}</button><span>${esc(p.status)}</span></div>`).join(''):'<div class="project-empty">Nenhum projeto vinculado.</div>'}<div class="project-head" style="margin-top:18px"><div class="project-label">▤ TAREFAS (${tasks.length})</div><button type="button" class="c-btn" data-project="new-task" data-id="${c.id}">＋ Tarefa</button></div>${tasks.length?tasks.map(t=>`<div class="project-entry task"><div><strong>${esc(t.title)}</strong><small>Prazo: ${t.due?formatDate(t.due):'Sem prazo'} · ${esc(getProject(t.projectId)?.name||'Sem projeto')}</small></div><select data-project="status" data-id="${t.id}" aria-label="Status de ${esc(t.title)}"><option value="A Fazer" ${!t.done&&t.status!=='Em Progresso'?'selected':''}>A Fazer</option><option value="Em Progresso" ${t.status==='Em Progresso'?'selected':''}>Em Progresso</option><option value="Concluído" ${t.done?'selected':''}>Concluído</option></select></div>`).join(''):'<div class="project-empty">Nenhuma tarefa vinculada.</div>'}`}
function refreshProjectPanel(){const c=clientsState.items.find(x=>x.id===clientsState.modal?.id),el=document.querySelectorAll('.client-modal .tab-panel')[2];if(el)el.innerHTML=projectPanel(c)}
function boardTasks(){const q=projectStore.query.toLocaleLowerCase('pt-BR');return dashState.tasks.filter(t=>(!projectStore.clientId||t.clientId===projectStore.clientId)&&(!projectStore.projectId||t.projectId===projectStore.projectId)&&(projectStore.showArchived||!t.archived)&&(!q||[t.title,t.client,getProject(t.projectId)?.name].some(x=>String(x||'').toLocaleLowerCase('pt-BR').includes(q))))}
function boardRow(t){const c=clientsState.items.find(c=>c.id===t.clientId),p=getProject(t.projectId),late=t.due&&t.due<dashToday()&&!t.done;return `<div class="board-row"><div class="board-title"><strong>${esc(t.title)}</strong><small>${esc(c?.name||'Sem cliente')} · ${esc(p?.name||'Sem projeto')}</small></div><select data-project="status" data-id="${t.id}" aria-label="Status de ${esc(t.title)}"><option value="A Fazer" ${!t.done&&t.status!=='Em Progresso'?'selected':''}>A Fazer</option><option value="Em Progresso" ${t.status==='Em Progresso'?'selected':''}>Em Progresso</option><option value="Concluído" ${t.done?'selected':''}>Concluído</option></select><span class="${late?'late':''}">${t.due?formatDate(t.due):'Sem prazo'}</span><button type="button" class="board-icon" data-project="edit-task" data-id="${t.id}">Editar</button><button type="button" class="board-icon" data-project="archive-task" data-id="${t.id}">${t.archived?'Restaurar':'Arquivar'}</button></div>`}
function renderKanban(){document.querySelector('.workspace').classList.remove('clients-mode','dashboard-mode');document.querySelector('.workspace').classList.add('kanban-mode');document.querySelector('#page-title').textContent='Kanban';const tasks=boardTasks(),today=dashToday(),late=tasks.filter(t=>t.due&&t.due<today&&!t.done),due=tasks.filter(t=>t.due===today&&!t.done),later=tasks.filter(t=>!late.includes(t)&&!due.includes(t));document.querySelector('.workspace').innerHTML=`<div class="board-shell"><div class="board-top"><div><h2>Kanban</h2><p>Projetos e tarefas por cliente</p></div><div class="board-buttons"><button type="button" class="c-btn ${projectStore.view==='list'?'active':''}" data-project="view-list">☰ Lista</button><button type="button" class="c-btn ${projectStore.view==='grid'?'active':''}" data-project="view-grid">▦ Quadro</button><button type="button" class="c-btn" data-project="new-project">＋ Novo Projeto</button><button type="button" class="c-btn primary" data-project="new-task">＋ Criar Tarefa</button></div></div><div class="board-filters"><select id="board-client" aria-label="Filtrar por cliente"><option value="">Todos os clientes</option>${clientsState.items.filter(c=>!c.archived).map(c=>`<option value="${c.id}" ${projectStore.clientId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select id="board-project" aria-label="Filtrar por projeto"><option value="">Todos os projetos</option>${projectStore.projects.filter(p=>!p.archived).map(p=>`<option value="${p.id}" ${projectStore.projectId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><input id="board-search" type="search" placeholder="Buscar tarefas..." value="${esc(projectStore.query)}" aria-label="Buscar tarefas"><label><input type="checkbox" id="board-archived" ${projectStore.showArchived?'checked':''}> Ver arquivadas</label></div><div class="board-content ${projectStore.view==='grid'?'columns':''}">${[['Atrasadas',late],['Hoje',due],['Próximas e concluídas',later]].map(([name,rows])=>`<section class="board-group"><h3>${name} <span>${rows.length}</span></h3>${rows.length?rows.map(boardRow).join(''):'<p class="board-empty">Nenhuma tarefa neste período.</p>'}</section>`).join('')}</div></div>`}
function openProjectForm(clientId='',id=''){const p=getProject(id);const root=document.createElement('div');root.className='project-dialog';root.innerHTML=`<div role="dialog" aria-modal="true" aria-label="${p?'Editar projeto':'Novo projeto'}"><h2>${p?'Editar projeto':'Novo projeto'}</h2><form id="project-form"><label>Nome do projeto<input name="name" value="${esc(p?.name)}" required maxlength="120"></label><label>Cliente<select name="clientId" required><option value="">Selecione o cliente</option>${clientsState.items.filter(c=>!c.archived).map(c=>`<option value="${c.id}" ${(p?.clientId||clientId)===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Status<select name="status"><option ${p?.status==='Ativo'?'selected':''}>Ativo</option><option ${p?.status==='Pausado'?'selected':''}>Pausado</option><option ${p?.status==='Concluído'?'selected':''}>Concluído</option></select></label><div class="dialog-actions"><button type="button" class="c-btn" data-project="close">Cancelar</button><button class="c-btn primary" type="submit">Salvar projeto</button></div></form></div>`;root.dataset.id=id;document.body.append(root);root.querySelector('input[name="name"]').focus()}
function openTaskForm(clientId='',id='',projectId=''){const task=dashState.tasks.find(t=>t.id===id);const root=document.createElement('div');root.className='project-dialog';root.innerHTML=`<div role="dialog" aria-modal="true" aria-label="${task?'Editar tarefa':'Nova tarefa'}"><h2>${task?'Editar tarefa':'Nova tarefa'}</h2><form id="task-form"><label>Título<input name="title" value="${esc(task?.title)}" required maxlength="160"></label><label>Cliente<select name="clientId" id="task-client" required><option value="">Selecione o cliente</option>${clientsState.items.filter(c=>!c.archived).map(c=>`<option value="${c.id}" ${(task?.clientId||clientId)===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Projeto<select name="projectId" id="task-project"><option value="">Sem projeto</option>${projectStore.projects.filter(p=>!p.archived).map(p=>`<option value="${p.id}" ${(task?.projectId||projectId)===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="form-grid"><label>Prazo<input name="due" type="date" value="${esc(task?.due)}"></label><label>Status<select name="status"><option ${task?.status==='A Fazer'?'selected':''}>A Fazer</option><option ${task?.status==='Em Progresso'?'selected':''}>Em Progresso</option><option ${task?.done?'selected':''}>Concluído</option></select></label></div><div class="dialog-actions"><button type="button" class="c-btn" data-project="close">Cancelar</button><button class="c-btn primary" type="submit">Salvar tarefa</button></div></form></div>`;root.dataset.id=id;document.body.append(root);root.querySelector('input[name="title"]').focus()}
function closeProjectForm(){document.querySelector('.project-dialog')?.remove()}
function refreshRelated(){if(document.querySelector('.workspace.kanban-mode'))renderKanban();refreshProjectPanel();if(document.querySelector('.workspace.dashboard-mode'))renderDashboard()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-project]');if(!b){if(e.target.classList.contains('project-dialog'))closeProjectForm();return}const a=b.dataset.project,id=b.dataset.id;if(a==='close')closeProjectForm();else if(a==='new-project')openProjectForm(id||projectStore.clientId);else if(a==='new-task')openTaskForm(id||projectStore.clientId);else if(a==='edit-task')openTaskForm('',id);else if(a==='open-project'){projectStore.projectId=id;projectStore.clientId=getProject(id)?.clientId||'';closeModal();menu.querySelector('[data-page="Kanban"]').click()}else if(a==='open-board'){projectStore.clientId=id;projectStore.projectId='';closeModal();menu.querySelector('[data-page="Kanban"]').click()}else if(a==='view-list'||a==='view-grid'){projectStore.view=a==='view-list'?'list':'grid';renderKanban()}else if(a==='archive-task'){const t=dashState.tasks.find(t=>t.id===id);if(t){t.archived=!t.archived;refreshRelated()}}});
document.addEventListener('change',e=>{if(e.target.dataset.project==='status'){const t=dashState.tasks.find(t=>t.id===e.target.dataset.id);if(t){t.status=e.target.value;t.done=t.status==='Concluído';refreshRelated()}}if(e.target.id==='board-client'){projectStore.clientId=e.target.value;projectStore.projectId='';renderKanban()}if(e.target.id==='board-project'){projectStore.projectId=e.target.value;renderKanban()}if(e.target.id==='board-archived'){projectStore.showArchived=e.target.checked;renderKanban()}});
document.addEventListener('input',e=>{if(e.target.id==='board-search'){projectStore.query=e.target.value;const pos=e.target.selectionStart;renderKanban();const input=document.querySelector('#board-search');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('submit',e=>{if(!['project-form','task-form'].includes(e.target.id))return;e.preventDefault();const root=e.target.closest('.project-dialog'),v=Object.fromEntries(new FormData(e.target));if(e.target.id==='project-form'){if(!v.clientId){toast('Escolha um cliente.');return}const p=getProject(root.dataset.id);if(p)Object.assign(p,{name:v.name.trim(),clientId:v.clientId,status:v.status});else projectStore.projects.push({id:'p-'+Date.now(),name:v.name.trim(),clientId:v.clientId,status:v.status,archived:false})}else{if(!v.clientId){toast('Escolha um cliente.');return}const t=dashState.tasks.find(t=>t.id===root.dataset.id),client=clientsState.items.find(c=>c.id===v.clientId),data={title:v.title.trim(),clientId:v.clientId,client:client?.name||'',projectId:v.projectId,due:v.due,status:v.status,done:v.status==='Concluído'};if(t)Object.assign(t,data);else dashState.tasks.unshift({id:'t-'+Date.now(),...data,archived:false})}closeProjectForm();refreshRelated();toast('Alteração atualizada no cliente e no Kanban nesta visualização.')});
